<?php require dirname(__DIR__).'/includes/bootstrap.php';$u=require_role(['KHACH_HANG']);$id=get('id');$h=contract($id,$u);must($h['trang_thai_hd']==='HOAN_TAT'&&$h['ngay_ban_giao'],'Chỉ đánh giá hợp đồng đã bàn giao.');handle_form(function()use($u,$id){$stars=filter_var(post('so_sao'),FILTER_VALIDATE_INT);must($stars&&$stars>=1&&$stars<=5,'Điểm từ 1 đến 5.');execute('INSERT INTO danh_gia(so_hop_dong,tai_khoan_id,so_sao,nhan_xet) VALUES(?,?,?,?)',[$id,$u['id'],$stars,valid_text(post('nhan_xet'),4000,false)]);},'khach_hang/danh_gia.php?id='.$id);page_start('Đánh giá trải nghiệm');$old=db_one('SELECT * FROM danh_gia WHERE so_hop_dong=?',[$id]);if($old)notice('Bạn đã đánh giá '.(int)$old['so_sao'].' sao: '.$old['nhan_xet']);else{echo '<div class="auth panel">';token_form();select_field('so_sao','Điểm đánh giá',['5'=>'★★★★★ · Rất hài lòng','4'=>'★★★★ · Hài lòng','3'=>'★★★ · Bình thường','2'=>'★★ · Chưa hài lòng','1'=>'★ · Không hài lòng'],'5',true);textarea('nhan_xet','Nhận xét');echo '<button>Gửi đánh giá</button></form></div>';}page_end();
